import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, escrita a mano.
 *
 * Presentacional y nada más: pinta las filas **en el orden que las recibe** —el
 * orden es del servidor (`fetchThreadPage` ordena por `last_item_at` descendente)—
 * y avisa con el ID del hilo cuando alguien abre una. No carga datos ni pagina.
 *
 * Tres cosas de este fichero son deliberadas y no cosméticas:
 *
 * - **Cada hilo va en un `<li>` sin `role`**, y el control pulsable es un
 *   `<button>` DE DENTRO (F-131). Un `role="button"` en el `<li>` lo sustituye,
 *   no se suma: `listitem` desaparece y `getByRole('button', { name: /…/ })`
 *   encontraría dos botones con el mismo nombre. El `<ul>` tampoco se pisa: es
 *   `list` y no lleva rol.
 * - **El estado vacío va en un `<div>`, nunca en un `<li>` dentro del `<ul>`**
 *   (F-141): con `threads` vacío el contrato exige que no quede ni un
 *   `listitem` en el documento.
 * - **El tono sale de `stateTone` y se traduce a clase aquí**, nunca a un color:
 *   el hex de la spec §3 vive en el CSS, que es su sitio (F-027 / F-003).
 */

/**
 * Tono → clase. El valor es `string | undefined` y no `string` a secas porque
 * con `noUncheckedIndexedAccess` cualquier propiedad de un CSS Module puede no
 * existir (F-143); el `??` que lo resuelve va en el único punto de consumo, para
 * que una clase que falte deje la fila sin adorno en vez de escribir la palabra
 * `undefined` en el atributo.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  // Sin hilos no se pinta una lista vacía colgando: se pinta el estado vacío de
  // la spec §6. El botón del Directorio va `disabled` con su motivo visible —
  // DIR-01 no está entre las pantallas del MVP, y un botón que parece pulsable y
  // no lleva a ningún sitio es la regla de CLAUDE.md §7 en la interfaz (F-128).
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>
          El Directorio (DIR-01) queda fuera del MVP: por eso el botón está apagado.
        </p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <button
            type="button"
            className={styles.rowBtn}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.rowTop}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry !== '' && (
                <span className={styles.country}>{thread.counterpartyCountry}</span>
              )}
            </span>
            <span className={styles.ts}>{relativeTime(thread.lastItemAt, now)}</span>
            <span className={styles.rowBottom}>
              {/* Metadatos del último elemento, nunca contenido descifrado (§7). */}
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.badge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}>
                {thread.state}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}

