import { useEffect, useState, type FormEvent, type KeyboardEvent } from 'react';

import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — panel de contenido.
 *
 * Esta es LA PANTALLA, no un componente de presentación: llama a
 * `fetchThreadPage` con `profile.orgId` y es dueña del estado de búsqueda y de
 * página. Las filas las pinta `ThreadList`, que no sabe de red.
 *
 * Lo que la spec cerrada pide y el mock no puede dar, resuelto aquí:
 *
 * - **La búsqueda filtra al pulsar Enter** (§3), no en cada tecla. Se resuelve en
 *   el servidor y sobre la página entera, nunca filtrando la página ya cargada:
 *   un «no hay resultados» falso no se distingue de uno cierto.
 * - **`Nuevo contacto` existe y está apagado** con su motivo a la vista: abre
 *   DIR-01, que no está entre las 8 pantallas del alcance (Plan §9 / F-023 e).
 * - **No hay botón de frase de seguridad**: en el MVP las claves viven en memoria
 *   de sesión y no hay frase, copia ni recuperación (CLAUDE.md §4). Queda el
 *   aviso informativo, sin botón.
 * - **No hay punto azul de no leídos**: el esquema no guarda lectura de ningún
 *   tipo, así que un recuento sería un número inventado delante del socio (F-023).
 * - **No hay contador de «25 hilos nuevos por día»**: es una regla de negocio sin
 *   implementación en el MVP y no se simula.
 */

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Firma pública del componente (F-118): el shell la pasa desde `App.tsx`, y sin
   * declararla el repo no compila desde este lado. **Se recibe y se ignora**:
   * MSG-02 no existía cuando se escribió esta tarea y abrir un hilo no lleva a
   * ningún sitio. No cambia nada de lo que se pide aquí.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * El texto del error, con el error de verdad dentro (F-128 / F-020).
 *
 * PostgREST rechaza con un objeto plano `{ code, message }`: `String(e)` daría
 * `[object Object]` y `e.message` daría `undefined`, y la pantalla se comería el
 * `PGRST201` que explica el fallo entero. Se sacan `code` y `message` cuando
 * existen y se pintan junto a la frase para humanos.
 */
function describeError(e: unknown): string {
  if (e instanceof Error) {
    return e.message !== '' ? e.message : e.name;
  }
  if (typeof e === 'object' && e !== null) {
    const flat = e as { code?: unknown; message?: unknown; details?: unknown; hint?: unknown };
    const parts: string[] = [];
    if (typeof flat.message === 'string' && flat.message !== '') parts.push(flat.message);
    if (typeof flat.details === 'string' && flat.details !== '') parts.push(flat.details);
    if (typeof flat.hint === 'string' && flat.hint !== '') parts.push(flat.hint);
    if (typeof flat.code === 'string' && flat.code !== '') parts.push(`código ${flat.code}`);
    if (parts.length > 0) return parts.join(' · ');
    try {
      return JSON.stringify(e) ?? 'error sin detalle';
    } catch {
      return 'error sin detalle';
    }
  }
  return String(e);
}

export function Messages({ profile, now }: MessagesProps) {
  const currentNow = now ?? new Date();

  /** Lo que hay escrito en el input. */
  const [query, setQuery] = useState('');
  /** Lo que se llegó a consultar al pulsar Enter. */
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((res) => {
        if (cancelled) return;
        setThreads(res.threads);
        setTotal(res.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(describeError(e));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const submitSearch = () => {
    setSearch(query);
    setPage(1);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    submitSearch();
  };

  // Enter se atiende también aquí porque el formulario no lleva botón de envío
  // visible: así la búsqueda se dispara igual con teclado y una sola vez.
  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      submitSearch();
    }
  };

  // MSG-02 no existe en el MVP: abrir un hilo no lleva a ningún sitio (F-023 e).
  // El botón de fila sigue existiendo porque el rol `listitem` no se puede pisar.
  const handleOpen = () => {
    /* sin destino */
  };

  const pages = pageCount(total);
  const pageNumbers = Array.from({ length: pages }, (_, i) => i + 1);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.e2ee}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>
          Contenido cifrado de extremo a extremo. En este MVP las claves viven en la memoria de la
          sesión: no hay frase de seguridad, copia de seguridad ni recuperación.
        </span>
      </div>

      <div className={styles.actions}>
        <form className={styles.searchForm} onSubmit={handleSubmit}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            className={styles.searchInput}
            type="text"
            value={query}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={handleKeyDown}
          />
        </form>

        <div className={styles.newContact}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeHint} data-testid="directorio-scope">
            Abre el Directorio de Organizaciones (DIR-01), que queda fuera del MVP: por eso está apagado.
          </span>
        </div>

        <span className={styles.count} data-testid="pag-info">
          {total.toLocaleString('es-ES')} hilos · Página {page} de {pages}
        </span>
      </div>

      {error !== null && (
        <div className={styles.error} role="alert">
          No se pudieron cargar los hilos. {error}
        </div>
      )}

      {loading ? (
        <p className={styles.loading}>Cargando hilos…</p>
      ) : (
        <ThreadList threads={threads} now={currentNow} onOpen={handleOpen} />
      )}

      {pages > 1 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={`${styles.page} ${styles.pageCtrl}`}
            aria-label="Página anterior"
            disabled={page === 1}
            onClick={() => setPage(page - 1)}
          >
            ‹
          </button>
          {/* El número va como TEXTO del botón y sin `aria-label`: un aria-label
              sustituye al nombre accesible y deja el botón llamándose otra cosa
              (F-145). */}
          {pageNumbers.map((n) => (
            <button
              key={n}
              type="button"
              className={n === page ? `${styles.page} ${styles.pageActive}` : styles.page}
              onClick={() => setPage(n)}
            >
              {n}
            </button>
          ))}
          <button
            type="button"
            className={`${styles.page} ${styles.pageCtrl}`}
            aria-label="Página siguiente"
            disabled={page === pages}
            onClick={() => setPage(page + 1)}
          >
            ›
          </button>
        </div>
      )}
    </div>
  );
}

