/* MSG-01 · Lista de Hilos — panel de contenido.
   Ningún color literal: todo sale de los tokens de design-system.md §1. */

.screen {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
}

.eyebrow {
  margin: 0;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-brand);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  color: var(--bw-steel-mist);
}

.title {
  margin: 0;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* Aviso E2EE informativo. Sin botón: en el MVP no hay frase de seguridad, copia
   ni recuperación, y un botón que no lleva a ningún sitio es F-023 e. */
.e2ee {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--bw-brass-border);
  border-radius: 5px;
  background: var(--bw-tag-bg);
  color: var(--bw-ink-steel);
  font-size: 12px;
  line-height: 1.5;
}

.e2ee i {
  color: var(--bw-brass);
  font-size: 13px;
  line-height: 1.4;
}

.actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.searchForm {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  max-width: 320px;
}

.searchForm i {
  position: absolute;
  left: 10px;
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  color: var(--bw-input-text);
  font-family: inherit;
  font-size: var(--bw-size-input);
  outline: none;
  transition: border-color 0.15s;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.newContact {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  border: 1px solid var(--bw-calibration-blue);
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  cursor: pointer;
